('CULTURE_PROSTATIC','Prostatic Fluid Culture',array[]::text[],'panel','Clinical Microbiology','panel','{"clinical_category":"microbiology_culture","specimen":"Prostatic secretion / post-massage urine","method":"Aerobic bacterial culture with organism identification; anaerobic/fungal/fastidious work-up only when specifically requested and validated.","patient_preparation":{"antimicrobials":"Collect before antimicrobial therapy when feasible; record recent antimicrobial use."},"collection_requirements":{"patient_preparation":"Collect expressed prostatic secretion or post-massage urine using documented method; avoid contamination.","collection":"Sterile container; record fraction and collection method.","container":"Sterile container or validated specimen-specific transport device."},"specimen_requirements":{"specimen":"Prostatic secretion / post-massage urine","quality":"Record anatomical site, collection method and specimen quality."},"transport_requirements":{"guidance":"Prompt transport; follow validated local protocol."},"stability_requirements":{"note":"Specimen- and transport-medium-specific. Follow IDSA/ASM 2024, manufacturer instructions and locally validated SOP; no universal stability interval."},"rejection_criteria":["Unlabeled fraction, contamination, or wrong container.","Mislabeled or leaking container"],"reporting_notes":"Report growth/no growth, isolate identification and isolate-specific antimicrobial susceptibility only when indicated and performed by a validated method. A negative culture does not exclude organisms not targeted or not recoverable by the selected method. AST interpretation must be tied to the adopted current CLSI/EUCAST edition.","source_references":[{"id":"IDSA-ASM-2024","title":"Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update","organization":"IDSA/ASM","year":2024,"doi":"10.1093/cid/ciae104","url":"https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499","scope":"Specimen selection, collection, transport, and microbiology test utilization."}]}'),
('CULTURE_THROAT','Throat Swab Culture',array[]::text[],'panel','Clinical Microbiology','panel','{"clinical_category":"microbiology_culture","specimen":"Throat / pharyngeal swab","method":"Aerobic bacterial culture with organism identification; anaerobic/fungal/fastidious work-up only when specifically requested and validated.","patient_preparation":{"antimicrobials":"Collect before antimicrobial therapy when feasible; record recent antimicrobial use."},"collection_requirements":{"patient_preparation":"Swab tonsillar pillars and posterior pharynx avoiding tongue and oral surfaces; record suspected pathogen when relevant.","collection":"Appropriate swab in validated transport medium.","container":"Sterile container or validated specimen-specific transport device."},"specimen_requirements":{"specimen":"Throat / pharyngeal swab","quality":"Record anatomical site, collection method and specimen quality."},"transport_requirements":{"guidance":"Prompt transport; follow organism-specific culture protocol."},"stability_requirements":{"note":"Specimen- and transport-medium-specific. Follow IDSA/ASM 2024, manufacturer instructions and locally validated SOP; no universal stability interval."},"rejection_criteria":["Saliva-contaminated or incorrectly collected specimen.","Mislabeled or leaking container"],"reporting_notes":"Report growth/no growth, isolate identification and isolate-specific antimicrobial susceptibility only when indicated and performed by a validated method. A negative culture does not exclude organisms not targeted or not recoverable by the selected method. AST interpretation must be tied to the adopted current CLSI/EUCAST edition.","source_references":[{"id":"IDSA-ASM-2024","title":"Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update","organization":"IDSA/ASM","year":2024,"doi":"10.1093/cid/ciae104","url":"https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499","scope":"Specimen selection, collection, transport, and microbiology test utilization."}]}'),
('CULTURE_EAR','Ear Swab Culture',array[]::text[],'panel','Clinical Microbiology','panel','{"clinical_category":"microbiology_culture","specimen":"Ear swab / ear discharge","method":"Aerobic bacterial culture with organism identification; anaerobic/fungal/fastidious work-up only when specifically requested and validated.","patient_preparation":{"antimicrobials":"Collect before antimicrobial therapy when feasible; record recent antimicrobial use."},"collection_requirements":{"patient_preparation":"Record external canal versus middle-ear aspirate; aspirate preferred for middle-ear infection where feasible.","collection":"Swab transport device or sterile aspirate container.","container":"Sterile container or validated specimen-specific transport device."},"specimen_requirements":{"specimen":"Ear swab / ear discharge","quality":"Record anatomical site, collection method and specimen quality."},"transport_requirements":{"guidance":"Prompt transport; anaerobic transport if requested and validated."},"stability_requirements":{"note":"Specimen- and transport-medium-specific. Follow IDSA/ASM 2024, manufacturer instructions and locally validated SOP; no universal stability interval."},"rejection_criteria":["No site details or dry/contaminated swab.","Mislabeled or leaking container"],"reporting_notes":"Report growth/no growth, isolate identification and isolate-specific antimicrobial susceptibility only when indicated and performed by a validated method. A negative culture does not exclude organisms not targeted or not recoverable by the selected method. AST interpretation must be tied to the adopted current CLSI/EUCAST edition.","source_references":[{"id":"IDSA-ASM-2024","title":"Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update","organization":"IDSA/ASM","year":2024,"doi":"10.1093/cid/ciae104","url":"https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499","scope":"Specimen selection, collection, transport, and microbiology test utilization."}]}'),
('CULTURE_NASAL','Nasal Swab Culture',array[]::text[],'panel','Clinical Microbiology','panel','{"clinical_category":"microbiology_culture","specimen":"Nasal swab","method":"Aerobic bacterial culture with organism identification; anaerobic/fungal/fastidious work-up only when specifically requested and validated.","patient_preparation":{"antimicrobials":"Collect before antimicrobial therapy when feasible; record recent antimicrobial use."},"collection_requirements":{"patient_preparation":"Record anterior nares versus nasopharynx and requested organism; use validated swab type.","collection":"Validated swab transport medium.","container":"Sterile container or validated specimen-specific transport device."},"specimen_requirements":{"specimen":"Nasal swab","quality":"Record anatomical site, collection method and specimen quality."},"transport_requirements":{"guidance":"Prompt transport; organism-specific media as required."},"stability_requirements":{"note":"Specimen- and transport-medium-specific. Follow IDSA/ASM 2024, manufacturer instructions and locally validated SOP; no universal stability interval."},"rejection_criteria":["Incorrect site or swab type.","Mislabeled or leaking container"],"reporting_notes":"Report growth/no growth, isolate identification and isolate-specific antimicrobial susceptibility only when indicated and performed by a validated method. A negative culture does not exclude organisms not targeted or not recoverable by the selected method. AST interpretation must be tied to the adopted current CLSI/EUCAST edition.","source_references":[{"id":"IDSA-ASM-2024","title":"Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update","organization":"IDSA/ASM","year":2024,"doi":"10.1093/cid/ciae104","url":"https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499","scope":"Specimen selection, collection, transport, and microbiology test utilization."}]}'),
('CULTURE_CONJUNCTIVAL','Conjunctival Swab Culture',array[]::text[],'panel','Clinical Microbiology','panel','{"clinical_category":"microbiology_culture","specimen":"Conjunctival swab","method":"Aerobic bacterial culture with organism identification; anaerobic/fungal/fastidious work-up only when specifically requested and validated.","patient_preparation":{"antimicrobials":"Collect before antimicrobial therapy when feasible; record recent antimicrobial use."},"collection_requirements":{"patient_preparation":"Collect from conjunctival sac using appropriate sterile swab; document eye and site.","collection":"Appropriate swab/transport medium; alert lab if gonococcal or other fastidious pathogen suspected.","container":"Sterile container or validated specimen-specific transport device."},"specimen_requirements":{"specimen":"Conjunctival swab","quality":"Record anatomical site, collection method and specimen quality."},"transport_requirements":{"guidance":"Immediate/prompt transport and organism-specific media."},"stability_requirements":{"note":"Specimen- and transport-medium-specific. Follow IDSA/ASM 2024, manufacturer instructions and locally validated SOP; no universal stability interval."},"rejection_criteria":["Wrong eye/site, dry swab, or transport delay.","Mislabeled or leaking container"],"reporting_notes":"Report growth/no growth, isolate identification and isolate-specific antimicrobial susceptibility only when indicated and performed by a validated method. A negative culture does not exclude organisms not targeted or not recoverable by the selected method. AST interpretation must be tied to the adopted current CLSI/EUCAST edition.","source_references":[{"id":"IDSA-ASM-2024","title":"Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update","organization":"IDSA/ASM","year":2024,"doi":"10.1093/cid/ciae104","url":"https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499","scope":"Specimen selection, collection, transport, and microbiology test utilization."}]}')
) as v(code,name,aliases,kind,category,service_type,definition)
where r.version='taiba-core-2026.11.20-r1' on conflict(release_id,master_code) do nothing;

with culture_tests as (
 select id from public.master_catalog_tests
 where release_id=(select id from public.master_catalog_releases where version='taiba-core-2026.11.20-r1')
  and left(master_code,8)='CULTURE_'
), params(parameter_code,parameter_name,value_type,display_order,choices,is_required) as (
 values
 ('CULTURE_GROWTH','Culture growth status','choice',10,'["No growth","Growth","Mixed growth / possible contamination","Pending","Not performed"]'::jsonb,true),
 ('CULTURE_SPECIMEN_QUALITY','Specimen quality','choice',20,'["Acceptable","Suboptimal - interpret with caution","Rejected"]'::jsonb,false),
 ('CULTURE_IDENTIFICATION','Organism identification summary','text',30,'[]'::jsonb,false),
 ('CULTURE_GRAM_STAIN','Direct microscopy / Gram stain','text',40,'[]'::jsonb,false),
 ('CULTURE_AST_COMMENT','Antimicrobial susceptibility comment','text',50,'[]'::jsonb,false),
 ('CULTURE_REPORT_COMMENT','Final culture report comment','text',60,'[]'::jsonb,true)
)
insert into public.master_catalog_parameters(
 master_test_id,parameter_code,parameter_name,value_type,unit,decimal_places,reference_ranges,choices,
 display_order,is_required,result_source,formula,clinical_metadata,source_references,clinical_review_status,reference_interval_status
)
select t.id,p.parameter_code,p.parameter_name,p.value_type,null,0,'[]'::jsonb,p.choices,
 p.display_order,p.is_required,'manual',null,jsonb_build_object('section','Culture result','group','Culture result'),
 jsonb_build_array(jsonb_build_object('id','IDSA-ASM-2024','title','Guide to Utilization of the Microbiology Laboratory for Diagnosis of Infectious Diseases: 2024 Update','doi','10.1093/cid/ciae104','url','https://academic.oup.com/cid/advance-article/doi/10.1093/cid/ciae104/7619499')),
 'verified','not_applicable'
from culture_tests t cross join params p;
